import{c as t,Q as a,j as s,m as i}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"Hyperliquid & Web3 Asset Recovery Glossary","description":"Key terminology for understanding high-risk address restrictions: flagged address, Arbitrum L2, L1 settlement, undelegated state, and service fees.","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/en/glossary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/glossary"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/glossary"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/glossary"}],["meta",{"name":"keywords","content":"Web3 glossary, DeFi recovery terms, flagged address definition, blockchain terminology"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"Hyperliquid & Web3 Asset Recovery Glossary"}],["meta",{"property":"og:description","content":"Key terminology for understanding high-risk address restrictions: flagged address, Arbitrum L2, L1 settlement, undelegated state, and service fees."}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/en/glossary"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"Hyperliquid & Web3 Asset Recovery Glossary"}],["meta",{"name":"twitter:description","content":"Key terminology for understanding high-risk address restrictions: flagged address, Arbitrum L2, L1 settlement, undelegated state, and service fees."}]]},"headers":[],"relativePath":"en/glossary.md","filePath":"en/glossary.md","lastUpdated":null}'),o={name:"en/glossary.md"};function r(l,e,n,d,c,u){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>This page explains the common words you may see during detection and recovery.</p><h2 id="fee-terms" tabindex="-1">Fee Terms <a class="header-anchor" href="#fee-terms" aria-label="Permalink to &quot;Fee Terms&quot;">​</a></h2><ul><li><code>Service Fee</code>: 0.5% of recovered value, minimum 1 USDC.</li><li><code>Withdrawal Fees</code>: Hyperliquid withdrawal fee, usually 2 USDC total.</li><li><code>Total Cost</code>: <code>Service Fee + Withdrawal Fees</code>.</li><li><code>You Will Receive</code>: estimated/actual user settlement amount.</li></ul><h2 id="accounts-and-assets" tabindex="-1">Accounts and Assets <a class="header-anchor" href="#accounts-and-assets" aria-label="Permalink to &quot;Accounts and Assets&quot;">​</a></h2><ul><li><code>SPOT</code>: regular token balances in your spot account.</li><li><code>PERP</code>: perpetual positions or balances related to perpetual trading.</li><li><code>VAULT</code>: assets held in vaults; some may be temporarily locked.</li><li><code>STAKED</code>: HYPE balances that are in a staking-related state.</li></ul><h2 id="staking-states" tabindex="-1">Staking States <a class="header-anchor" href="#staking-states" aria-label="Permalink to &quot;Staking States&quot;">​</a></h2><ul><li><code>HYPE-STAKED</code>: HYPE is still actively staked and cannot be withdrawn immediately.</li><li><code>HYPE-UNSTAKED</code>: HYPE has left active staking and is ready for a later step.</li><li><code>HYPE-PENDING</code>: withdrawal has been initiated and is still in the waiting period.</li></ul><h2 id="step-level-statuses" tabindex="-1">Step-Level Statuses <a class="header-anchor" href="#step-level-statuses" aria-label="Permalink to &quot;Step-Level Statuses&quot;">​</a></h2><ul><li><code>completed</code>: this step finished successfully.</li><li><code>completed_partial</code>: this step finished only in part; some assets may still need follow-up.</li><li><code>completed_waiting</code>: this step finished, but you must wait before the next action.</li><li><code>skipped_locked</code>: this step was skipped because the asset is currently locked.</li><li><code>skipped_no_assets</code>: this step was skipped because there was nothing eligible to process.</li><li><code>failed_*</code>: this step failed because of a system, input, or network issue.</li></ul><h2 id="task-level-outcomes" tabindex="-1">Task-Level Outcomes <a class="header-anchor" href="#task-level-outcomes" aria-label="Permalink to &quot;Task-Level Outcomes&quot;">​</a></h2><ul><li><code>completed</code>: this run made real progress or recovered funds, and you do not need to rerun it right now.</li><li><code>partial</code>: this run only finished in part, or nothing was recovered yet while some assets are still blocked or waiting.</li><li><code>waiting_to_rerun</code>: this run progressed correctly, but you still need to wait and run it again later.</li><li><code>failed</code>: this run stopped because of a fatal error.</li></ul>',12)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
